const CACHE='hocco-message-shell-v54';
const SHELL=['/assets/cinema/streaming-hero.webp','/assets/cinema/streaming-live.webp','/assets/cinema/streaming-city.webp','/assets/cinema/origin-v2.webp','/assets/cinema/instant-v2.webp','/assets/cinema/transformation-v2.webp','/','/index.html','/cliente/','/cliente/index.html','/cliente/entry.mjs','/ir-alem/','/ir-alem/index.html','/ir-alem/app.mjs','/style.css','/cinema.css','/location.mjs','/assets/cinema/community-art.webp','/assets/cinema/live-art.webp','/assets/hocco-message-512.png','/city-offers.mjs','/navigation-ui.mjs','/assets/cinema/metamorphosis.webp','/assets/cinema/choices.webp','/cinema.mjs','/cinema-shell.mjs','/assets/cinema/hero.webp','/assets/cinema/live.webp','/avatars.mjs','/app.mjs','/carousel-advisory.mjs','/community-carousel.mjs','/community-reactions.mjs','/purchase-draft.mjs','/support.mjs','/pwa.mjs','/config.mjs','/payment-state.mjs','/pix.mjs','/policies.mjs','/manifest.webmanifest','/assets/figurantes-portraits-v3.webp','/assets/figurantes-body-v2.webp','/assets/hocco-message-icon.svg','/assets/hocco-message-192.png','/assets/hocco-message-video.mp4','/assets/comunidade-hocco.webp'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/')||url.pathname.endsWith('.mp3')||event.request.headers.has('range'))return;if(/^\/(?:controle|equipe)(?:\/|$)/.test(url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const clone=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,clone))}return response}).catch(()=>caches.match(event.request).then(response=>response||(event.request.mode==='navigate'?caches.match('/index.html'):Response.error()))))});
